#!/usr/bin/env python3
"""Builds story/shots.json from a compact shot list keyed to transcript sentence numbers.
Each shot starts 0.15 s before its sentence (or before a given word inside it) and ends where the next begins.
Run: python3 story/build_shots.py  (Perfect Memory)   (from the project folder)"""
import json, os, re
HERE = os.path.dirname(os.path.abspath(__file__)); PROJ = os.path.dirname(HERE)
SENT = json.load(open(os.path.join(PROJ, 'timeline/sentences.json')))
WORDS = json.load(open(os.path.join(PROJ, 'timeline/words.json')))['words']
CFG = json.load(open(os.path.join(PROJ, 'config.json')))
DUR = round(CFG['duration'] + 1.5, 2)

def norm(w): return re.sub(r"[^\w']", '', w.lower())
def t_of(line, word=None):
    s = SENT[line - 1]
    if not word: return s['start']
    for w in WORDS:
        if w['start'] >= s['start'] - 0.05 and w['start'] <= s['end'] + 0.05 and norm(w['word']).startswith(norm(word)): return w['start']
    raise SystemExit(f'word {word!r} not in line {line}: {s["text"]}')

# ---------- param helpers
def c(id, x=0.5, pose='stand', expr='neutral', f=1, **kw): return dict(c=id, x=x, pose=pose, expr=expr, f=f, **kw)
def A(set, *cast, **kw): return dict(tpl='act', set=set, cast=list(cast), **kw)
def F(who, expr, set, **kw): return dict(tpl='face', who=who, expr=expr, set=set, **kw)
def I(obj, set=None, **kw): d = dict(tpl='ins', obj=obj, **kw); d.update({'set': set} if set else {}); return d
def B(d, **kw): return dict(tpl='bp', d=d, **kw)
def K(set, *txt, **kw): return dict(tpl='card', set=set, txt=list(txt), **kw)
def T(s, at=None, **kw): d = dict(s=s, **kw); d.update({'at': at} if at is not None else {}); return d
def PM(kind, sub=None, set='class', subAt=None): d = dict(tpl='pm', kind=kind, set=set); d.update({'sub': sub} if sub else {}); d.update({'subAt': subAt} if subAt else {}); return d
def X(t, **kw): return dict(type=t, **kw)
def S(name, at=0, gain=-8): return dict(at=at, name=name, gain=gain)

